input.content:
/* Kiln & Co — see DESIGN.md for the reasoning behind these tokens */

:root {
  color-scheme: light;

  /* Porcelain and iron: the studio's two ends of the colour range */
  --bg: oklch(0.97 0.006 210);       /* porcelain */
  --surface: oklch(0.935 0.008 210); /* porcelain in shade */
  --ink: oklch(0.24 0.025 45);       /* tenmoku iron */
  --muted: oklch(0.45 0.015 220);
  --accent: oklch(0.42 0.06 170);    /* deep celadon: actions only */
  --accent-press: oklch(0.34 0.055 170);
  --ring: var(--accent);
  --rule: oklch(0.52 0.02 60);       /* tile edges, dividers */

  /* Glazes: one per workshop, only ever on tiles */
  --clay: oklch(0.86 0.012 80);
  --celadon: oklch(0.74 0.06 165);
  --tenmoku: oklch(0.3 0.045 40);
  --chun: oklch(0.66 0.08 245);

  --display: "Palatino Linotype", Palatino, "Book Antiqua", "Iowan Old Style", Georgia, serif;
  --body: "Gill Sans", "Gill Sans MT", Seravek, "Segoe UI", system-ui, sans-serif;

  /* 1.333 scale */
  --step-0: 1.125rem;
  --step-1: 1.5rem;
  --step-2: 2rem;
  --step-3: clamp(2.25rem, 4vw, 2.67rem);
  --step-4: clamp(2.5rem, 6vw, 4.75rem);

  --space-1: 0.5rem;
  --space-2: 1rem;
  --space-3: 1.5rem;
  --space-4: 2.5rem;
  --space-5: 4rem;
  --space-6: 6.5rem;

  --ease-out: cubic-bezier(0.22, 1, 0.36, 1); /* quint */
}

*, *::before, *::after { box-sizing: border-box; }

html { -webkit-text-size-adjust: 100%; }

@media (prefers-reduced-motion: no-preference) {
  html { scroll-behavior: smooth; }
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--body);
  font-size: var(--step-0);
  line-height: 1.6;
  caret-color: var(--accent);
}

::selection { background: var(--celadon); color: var(--ink); }

h1, h2, h3 {
  font-family: var(--display);
  font-weight: 400;
  text-wrap: balance;
  margin: 0;
}

h1 { font-size: var(--step-4); line-height: 1.05; letter-spacing: -0.02em; }
h2 { font-size: var(--step-3); line-height: 1.15; letter-spacing: -0.01em; }
h3 { font-size: var(--step-1); line-height: 1.25; }

p { margin: 0; text-wrap: pretty; }

a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 0.2em; }

img { display: block; max-width: 100%; height: auto; }

:focus-visible {
  outline: 3px solid var(--ring);
  outline-offset: 3px;
  border-radius: 0.25rem;
}

.wrap {
  width: min(100% - 2 * var(--space-3), 72rem);
  margin-inline: auto;
}

.skip {
  position: absolute;
  left: var(--space-2);
  top: -10rem;
  z-index: 10;
  padding: 0.75rem 1rem;
  background: var(--ink);
  color: var(--bg);
  border-radius: 0.5rem;
}
.skip:focus { top: var(--space-2); }

/* ---------- Buttons ---------- */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 2.75rem;
  padding: 0.7rem 1.35rem;
  background: var(--accent);
  color: var(--bg);
  font-weight: 600;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  border-radius: 0.5rem;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease-out);
}
.btn:active { background: var(--accent-press); transform: translateY(1px); transition-duration: 60ms; }
@media (hover: hover) {
  .btn:hover { background: var(--accent-press); }
}
.btn-small { padding-inline: 1rem; font-size: 1rem; }

/* ---------- The signature: a glaze test tile ----------
   Raw clay on top, a punched hanging hole, glaze dipped over the lower part
   with an uneven edge, pooling darker at the foot. It always swings from its hole. */

.tile {
  --glaze: var(--celadon);
  --hole: var(--bg);
  position: relative;
  display: block;
  flex: none;
  width: var(--tile-w, 4rem);
  aspect-ratio: 3 / 4;
  background: var(--clay);
  border: 1px solid var(--rule);
  border-radius: 0.3rem;
  overflow: hidden;
  transform-origin: 50% 15%;
  box-shadow: 0 0.15rem 0.35rem oklch(0.24 0.025 45 / 0.18);
}
.tile::before {
  content: "";
  position: absolute;
  inset: 36% 0 0;
  background: linear-gradient(to bottom, var(--glaze) 55%, color-mix(in oklch, var(--glaze), black 28%));
  clip-path: polygon(0 9%, 11% 5%, 23% 12%, 36% 3%, 49% 10%, 61% 2%, 74% 9%, 87% 4%, 100% 8%, 100% 100%, 0 100%);
}
.tile::after {
  content: "";
  position: absolute;
  top: 9%;
  left: 50%;
  width: 17%;
  aspect-ratio: 1;
  translate: -50% 0;
  border-radius: 50%;
  background: var(--hole);
  box-shadow: inset 0 1px 2px oklch(0.24 0.025 45 / 0.45);
}
.tile-celadon { --glaze: var(--celadon); }
.tile-tenmoku { --glaze: var(--tenmoku); }
.tile-chun    { --glaze: var(--chun); }

/* ---------- Nav ---------- */

.nav {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-1) var(--space-3);
  padding-block: var(--space-2);
}
.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  min-height: 2.75rem;
  font-family: var(--display);
  font-size: 1.4rem;
  text-decoration: none;
}
.nav-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0 var(--space-1);
  margin: 0 0 0 auto;
  padding: 0;
  list-style: none;
}
.nav-links a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  padding-inline: 0.6rem;
  text-decoration: none;
}
@media (hover: hover) {
  .nav-links a:hover { text-decoration: underline; }
}

@media (max-width: 40em) {
  .nav-cta { margin-left: auto; }
  .nav-links { order: 3; width: 100%; margin: 0; }
  .nav-links li:first-child a { padding-left: 0; }
}

/* ---------- Hero ---------- */

.hero {
  display: grid;
  gap: var(--space-4);
  align-items: center;
  padding-block: var(--space-4) var(--space-6);
}
.hero-copy { max-width: 36rem; }
.lede {
  margin-top: var(--space-3);
  font-size: 1.25rem;
  max-width: 34ch;
}
.hero-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-3);
  margin-top: var(--space-4);
}
.hero-price { color: var(--muted); max-width: 24ch; font-size: 1rem; }

/* The rail: a batten with three tiles hanging at different drops */
.rail {
  position: relative;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  gap: clamp(1rem, 4vw, 2.5rem);
  padding-top: 1.1rem;
  --tile-w: clamp(5rem, 22vw, 8.5rem);
}
.rail::before {
  content: "";
  position: absolute;
  top: 0;
  left: 4%;
  right: 4%;
  height: 0.55rem;
  background: var(--ink);
  border-radius: 0.15rem;
}
.rail .tile:nth-child(2) { margin-top: 2.25rem; }
.rail .tile:nth-child(3) { margin-top: 0.75rem; }

@media (min-width: 56em) {
  .hero { grid-template-columns: 1.15fr 1fr; padding-top: var(--space-5); }
  .rail { --tile-w: clamp(6.5rem, 10vw, 9rem); }
}

/* ---------- Section heads ---------- */

.section-head {
  max-width: 40rem;
  margin-bottom: var(--space-4);
}
.section-head p { margin-top: var(--space-2); color: var(--muted); }
.section-head a { color: var(--ink); }

/* ---------- Workshops: a price list, not a card grid ---------- */

.workshops {
  background: var(--surface);
  padding-block: var(--space-6);
  scroll-margin-top: var(--space-2);
}
.menu { margin: 0; padding: 0; list-style: none; border-top: 1px solid var(--rule); }
.workshop {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: var(--space-2) var(--space-3);
  padding-block: var(--space-4);
  border-bottom: 1px solid var(--rule);
  --hole: var(--surface);
}
.workshop .tile { --tile-w: 3.5rem; transition: rotate 250ms var(--ease-out); }
.workshop-body { min-width: 0; max-width: 38rem; }
.workshop-body > p:last-child { margin-top: var(--space-1); }
.when { margin-top: 0.25rem; color: var(--muted); font-size: 1rem; }
.workshop-buy {
  grid-column: 1 / -1;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-2);
}
.price { display: flex; align-items: baseline; gap: 0.5rem; }
.amount {
  font-family: var(--display);
  font-size: var(--step-2);
  line-height: 1;
  font-variant-numeric: tabular-nums lining-nums;
}
.unit { color: var(--muted); font-size: 1rem; }

@media (min-width: 48em) {
  .workshop { grid-template-columns: auto 1fr 15rem; align-items: start; }
  .workshop .tile { --tile-w: 4.5rem; }
  .workshop-buy {
    grid-column: auto;
    flex-direction: column;
    align-items: flex-end;
    text-align: right;
  }
}

/* The tile swings from its hole when its row is pointed at or focused */
@media (prefers-reduced-motion: no-preference) {
  .workshop:focus-within .tile { rotate: -5deg; }
}
@media (prefers-reduced-motion: no-preference) and (hover: hover) {
  .workshop:hover .tile { rotate: -5deg; }
}

/* ---------- Studio photos ---------- */

.studio { padding-block: var(--space-6); }
.gallery {
  display: grid;
  gap: var(--space-3);
  margin: 0;
}
.shot { margin: 0; min-width: 0; }
.shot img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 0.25rem;
  background: var(--clay);
}
.shot figcaption { margin-top: 0.6rem; color: var(--muted); font-size: 1rem; }

@media (min-width: 48em) {
  .gallery {
    grid-template-columns: 1.4fr 1fr 1fr;
    grid-template-rows: auto auto;
    align-items: start;
  }
  .shot-large { grid-row: span 2; }
  .shot-wide { grid-column: span 2; }
  .shot-large img { aspect-ratio: 4 / 5; }
  .shot-wide img { aspect-ratio: 25 / 14; }
  .shot:not(.shot-large):not(.shot-wide) img { aspect-ratio: 1; }
}

/* ---------- Footer (deliberately dark: the kiln end of the range) ---------- */

.site-footer {
  background: var(--ink);
  color: var(--bg);
  padding-block: var(--space-5) var(--space-3);
  line-height: 1.7;
  letter-spacing: 0.01em;
  --ring: var(--bg);
}
.footer-grid {
  display: grid;
  gap: var(--space-4);
  grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr));
  align-items: start;
}
.site-footer h2 { font-size: var(--step-2); margin-bottom: var(--space-2); }
.site-footer h3 {
  font-family: var(--body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-1);
}
.site-footer p + p { margin-top: var(--space-1); }
.site-footer address { font-style: normal; }
.site-footer a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  overflow-wrap: anywhere;
}
.tile-large { --tile-w: 5.5rem; --hole: var(--ink); border-color: oklch(0.6 0.02 60); }
.small {
  margin-top: var(--space-5);
  padding-top: var(--space-2);
  border-top: 1px solid oklch(0.45 0.02 45);
  color: oklch(0.82 0.01 210);
  font-size: 0.95rem;
}

/* ---------- Entrance: tiles settle on their nails, once ---------- */

@media (prefers-reduced-motion: no-preference) {
  .rail .tile { animation: settle 700ms var(--ease-out) both; }
  .rail .tile:nth-child(2) { animation-delay: 90ms; }
  .rail .tile:nth-child(3) { animation-delay: 180ms; }
}
@keyframes settle {
  from { rotate: -6deg; }
  to { rotate: 0deg; }
}

