.site-footer h3 {
  font-family: var(--body);
  font-size: 1rem;
  font-weight: 600;
  margin-bottom: var(--space-1);
}
.site-footer p + p { margin-top: var(--space-1); }
.site-footer address { font-style: normal; }
.site-footer a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  overflow-wrap: anywhere;
}
.tile-large { --tile-w: 5.5rem; --hole: var(--ink); border-color: oklch(0.6 0.02 60); }
.small {
  margin-top: var(--space-5);
  padding-top: var(--space-2);
  border-top: 1px solid oklch(0.45 0.02 45);
  color: oklch(0.82 0.01 210);
  font-size: 0.95rem;
}

/* ---------- Entrance: tiles settle on their nails, once ---------- */

@media (prefers-reduced-motion: no-preference) {
  .rail .tile { animation: settle 700ms var(--ease-out) both; }
  .rail .tile:nth-child(2) { animation-delay: 90ms; }
  .rail .tile:nth-child(3) { animation-delay: 180ms; }
}
@keyframes settle {
  from { rotate: -6deg; }
  to { rotate: 0deg; }
}

tool_input.command:
awk 'function f(n){return n<=0.0031308?12.92*n:1.055*(n^(1/2.4))-0.055}
function cl(v){v=f(v); if(v<0)v=0; if(v>1)v=1; return int(v*255+0.5)}
function lin(v){v/=255; return v<=0.03928?v/12.92:((v+0.055)/1.055)^2.4}
function lum(L,C,H,  h,a,b,l,m,s,r,g,bb){h=H*3.14159265/180;a=C*cos(h);b=C*sin(h)
 l=(L+0.3963377774*a+0.2158037573*b)^3; m=(L-0.1055613458*a-0.0638541728*b)^3; s=(L-0.0894841775*a-1.2914855480*b)^3
 r=cl(4.0767416621*l-3.3077115913*m+0.2309699292*s); g=cl(-1.2684380046*l+2.6097574011*m-0.3413193965*s); bb=cl(-0.0041960863*l-0.7034186147*m+1.7076147010*s)
 HEX=sprintf("#%02x%02x%02x",r,g,bb); return 0.2126*lin(r)+0.7152*lin(g)+0.0722*lin(bb)}
function R(x,y,t){if(y>x){t=x;x=y;y=t}; return (x+0.05)/(y+0.05)}
BEGIN{
bg=lum(.97,.006,210); hb=HEX; ink=lum(.24,.025,45); hi=HEX; mu=lum(.45,.015,220); hm=HEX; act=lum(.42,.06,170); ha=HEX
acth=lum(.34,.055,170); hah=HEX; su=lum(.935,.008,210); hs=HEX; edge=lum(.52,.02,60); he=HEX; clay=lum(.86,.012,80); hc=HEX
fm=lum(.82,.01,210); hf=HEX; cel=lum(.74,.06,165); hce=HEX; chun=lum(.66,.08,245); hch=HEX
printf "bg %s ink %s muted %s act %s actH %s surf %s edge %s clay %s fmuted %s cel %s chun %s\n",hb,hi,hm,ha,hah,hs,he,hc,hf,hce,hch
printf "ink/bg %.2f muted/bg %.2f muted/surf %.2f ink/surf %.2f\n",R(ink,bg),R(mu,bg),R(mu,su),R(ink,su)
printf "bg/act %.2f bg/actH %.2f ring act/bg %.2f\n",R(bg,act),R(bg,acth),R(act,bg)
printf "footer bg/ink %.2f fmuted/ink %.2f ring bg/ink %.2f\n",R(bg,ink),R(fm,ink),R(bg,ink)
printf "edge/bg %.2f edge/clay %.2f edge/cel %.2f ink/cel %.2f edge/chun %.2f\n",R(edge,bg),R(edge,clay),R(edge,cel),R(ink,cel),R(edge,chun)}'
